from pathlib import Path
import sys
root=Path(sys.argv[1])
p=root/'public/math-duel.mjs';s=p.read_text().replace('MATH_VERSION=96','MATH_VERSION=97').replace('s.version!==96','s.version!==97').replace('s.version=96','s.version=97').replace('version:96','version:97')
s=s.replace("s.arrivalMotion??='up';", "s.arrivalMotion??='up';s.arrivalX??=s.arrivalSide==='left'?0:100;s.arrivalY??=65;")
s=s.replace("if(action==='arrivalSide'){", "if(action==='arrivalPosition'){const x=Number(value?.x),y=Number(value?.y);if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||x>100||y<0||y>100)throw Error('Bubble coordinates must be 0–100%');s.arrivalX=x;s.arrivalY=y;return true;}if(action==='arrivalSide'){")
s=s.replace("s.arrivalSide=value;return true;", "s.arrivalSide=value;s.arrivalX=value==='left'?0:100;return true;")
s=s.replace("return {version:97,", "return {version:97,arrivalX:s.arrivalX??(s.arrivalSide==='left'?0:100),arrivalY:s.arrivalY??65,")
p.write_text(s)
p=root/'public/math-duel-ui.mjs';s=p.read_text().replace('v=96','v=97').replace('math96','math97')
s=s.replace("Object.assign(labels.en,{", "Object.assign(labels.en,{arrivalX:'Horizontal position · left / right',arrivalY:'Vertical position · top / bottom',positionHelp:'Move the sliders, or drag the bubble in the preview. Position saves automatically.',positionPreview:'Preview',positionReset:'Reset bubble position',",1)
s=s.replace("Object.assign(labels.fa,{", "Object.assign(labels.fa,{arrivalX:'موقعیت افقی · چپ / راست',arrivalY:'موقعیت عمودی · بالا / پایین',positionHelp:'اسلایدرها را حرکت دهید یا حباب پیش‌نمایش را بکشید؛ موقعیت خودکار ذخیره می‌شود.',positionPreview:'پیش‌نمایش',positionReset:'بازنشانی موقعیت حباب',",1)
s=s.replace("arrivalMotion:'Bubble movement'", "arrivalMotion:'Bubble entrance animation'").replace("arrivalMotion:'حرکت حباب'", "arrivalMotion:'جهت ورود حباب'")
helper=r'''
let positionDraft=null,positionTimer=0,positionLastSent=0,positionDragging=false,positionDragOffset=null;
const positionClamp=n=>Math.max(0,Math.min(100,Math.round(Number(n)||0)));
function layoutArrival(scaleOverride){if(!latest)return;const pos=positionDraft||{x:latest.arrivalX??(latest.arrivalSide==='left'?0:100),y:latest.arrivalY??65},scale=scaleOverride??((latest.arrivalSize??100)/100);const width=220*scale,height=178*scale;if(screen){const bubble=$('arrivalBanner');bubble.style.left=(28+(1080-56-width)*pos.x/100)+'px';bubble.style.right='auto';bubble.style.setProperty('--arrival-top',(28+(1920-56-height)*pos.y/100)+'px');}const stage=$('arrivalPositionPreview'),handle=$('arrivalDragHandle');if(stage.clientWidth){const sx=stage.clientWidth/1080,sy=stage.clientHeight/1920;handle.style.width=(width*sx)+'px';handle.style.height=(height*sy)+'px';handle.style.left=((28+(1080-56-width)*pos.x/100)*sx)+'px';handle.style.top=((28+(1920-56-height)*pos.y/100)*sy)+'px';}for(const key of['x','y']){$('arrival'+key.toUpperCase()).value=String(pos[key]);$('arrival'+key.toUpperCase()+'Value').textContent=String(pos[key])+'%';}}
function flushArrivalPosition(){clearTimeout(positionTimer);positionTimer=0;positionLastSent=performance.now();if(positionDraft&&!send({type:'uiCommand',command:'mathControl',id:crypto.randomUUID(),action:'arrivalPosition',value:{...positionDraft}}))positionDraft=null;}
function moveArrivalPosition(x,y,finish=false){positionDraft={x:positionClamp(x),y:positionClamp(y)};layoutArrival();if(finish)flushArrivalPosition();else if(!positionTimer)positionTimer=setTimeout(flushArrivalPosition,Math.max(0,120-(performance.now()-positionLastSent)));}
function installArrivalPositionControls(){for(const key of['X','Y']){$('arrival'+key).oninput=()=>moveArrivalPosition($('arrivalX').value,$('arrivalY').value);$('arrival'+key).onchange=()=>moveArrivalPosition($('arrivalX').value,$('arrivalY').value,true);}$('arrivalPositionReset').onclick=()=>moveArrivalPosition(latest?.arrivalSide==='left'?0:100,65,true);const handle=$('arrivalDragHandle');handle.onpointerdown=e=>{if(!authed)return;e.preventDefault();positionDragging=true;const r=handle.getBoundingClientRect();positionDragOffset={x:e.clientX-r.left,y:e.clientY-r.top};handle.setPointerCapture(e.pointerId);};handle.onpointermove=e=>{if(!positionDragging||!positionDragOffset)return;const stage=$('arrivalPositionPreview'),r=stage.getBoundingClientRect(),scale=(latest?.arrivalSize??100)/100,sx=stage.clientWidth/1080,sy=stage.clientHeight/1920;const left=(e.clientX-r.left-stage.clientLeft-positionDragOffset.x)/sx,top=(e.clientY-r.top-stage.clientTop-positionDragOffset.y)/sy;moveArrivalPosition((left-28)/(1080-56-220*scale)*100,(top-28)/(1920-56-178*scale)*100);};const finish=()=>{if(!positionDragging)return;positionDragging=false;positionDragOffset=null;flushArrivalPosition();};handle.onpointerup=finish;handle.onpointercancel=finish;handle.onlostpointercapture=finish;handle.onkeydown=e=>{const delta=e.shiftKey?10:1,move={ArrowLeft:[-delta,0],ArrowRight:[delta,0],ArrowUp:[0,-delta],ArrowDown:[0,delta]}[e.key];if(!move)return;e.preventDefault();const p=positionDraft||{x:latest?.arrivalX??100,y:latest?.arrivalY??65};moveArrivalPosition(p.x+move[0],p.y+move[1],true);};}
'''
pos=s.index('\nfunction leaderRow');s=s[:pos]+helper+s[pos:]
old="if(screen){const q=document.querySelector('.quiz');root.style.setProperty('--arrival-top',(q.offsetTop+q.offsetHeight+10)+'px');}"
s=s.replace(old,"if(screen)layoutArrival();",1)
s=s.replace("function render(s){latest=s;", "function render(s){latest=s;if(positionDraft&&!positionDragging&&positionDraft.x===(s.arrivalX??100)&&positionDraft.y===(s.arrivalY??65))positionDraft=null;layoutArrival();")
s=s.replace("function selectSettingsTab(name,focus=false){", "function selectSettingsTab(name,focus=false){if(name==='live')requestAnimationFrame(()=>layoutArrival());")
s=s.replace("$('arrivalBanner').style.setProperty('--bubble-scale',String(Number($('arrivalSize').value)/100));", "$('arrivalBanner').style.setProperty('--bubble-scale',String(Number($('arrivalSize').value)/100));layoutArrival(Number($('arrivalSize').value)/100);")
s=s.replace("$('arrivalSide').onchange=()=>control('arrivalSide',$('arrivalSide').value);", "$('arrivalSide').onchange=()=>{positionDraft=null;clearTimeout(positionTimer);positionTimer=0;control('arrivalSide',$('arrivalSide').value);};")
s+='\ninstallArrivalPositionControls();addEventListener(\'resize\',()=>layoutArrival());\n'
p.write_text(s)
p=root/'public/math-duel.html';s=p.read_text().replace('v=96','v=97').replace('<p id="liveStatus"></p>', '<p id="liveStatus"></p><div class="arrival-position-controls"><label><span data-t="arrivalX">Horizontal position · left / right</span><input id="arrivalX" type="range" min="0" max="100" step="1" value="100"><output id="arrivalXValue" for="arrivalX">100%</output></label><label><span data-t="arrivalY">Vertical position · top / bottom</span><input id="arrivalY" type="range" min="0" max="100" step="1" value="65"><output id="arrivalYValue" for="arrivalY">65%</output></label><p data-t="positionHelp"></p><div id="arrivalPositionPreview" class="arrival-position-preview"><button id="arrivalDragHandle" type="button" class="arrival-drag-handle" aria-label="Drag bubble to position"><span>👤</span><small data-t="positionPreview">Preview</small></button></div><button id="arrivalPositionReset" type="button" data-t="positionReset">Reset bubble position</button></div>');p.write_text(s)
p=root/'public/math-duel.css'
with p.open('a')as f:f.write(r'''
.arrival-position-controls{padding:10px 0;border-bottom:1px solid #365276;margin-bottom:10px}.arrival-position-preview{position:relative;width:min(216px,100%);aspect-ratio:9/16;border:2px solid #486482;border-radius:8px;background:linear-gradient(#17263f 0 18%,#0b1930 18% 62%,#162841 62% 64%,#08162c 64%);overflow:hidden;margin:10px auto}.arrival-drag-handle{position:absolute;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:2px;border:0;background:transparent;color:#fff;padding:0;margin:0;cursor:grab;touch-action:none;user-select:none;min-width:0;min-height:0;box-shadow:none}.arrival-drag-handle:active{cursor:grabbing}.arrival-drag-handle>span{display:flex;align-items:center;justify-content:center;width:45%;aspect-ratio:1;border:2px solid #74f5d2;border-radius:50%;background:#183448;font-size:12px}.arrival-drag-handle>small{font-size:9px;line-height:1}.arrival-drag-handle:focus-visible{outline:2px solid #fff;outline-offset:2px}
''')
